import { useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (date: Date, days: number) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);

const isSameDay = (a: Date | null, b: Date | null) =>
  !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [innerValue, setInnerValue] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : innerValue;

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: shiftDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: shiftDays(today, -7) },
    ];
  }, []);

  const commit = (next: Date | null) => {
    if (value === undefined) setInnerValue(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxWidth: '320px' }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {presets.map((preset) => {
          const active = isSameDay(selected, preset.date);
          return (
            <JxChip
              key={preset.id}
              active={active}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => commit(preset.date)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  commit(preset.date);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale="ru-RU" value={selected} onValueChange={commit} />

      <p
        aria-live="polite"
        style={{
          margin: 0,
          fontFamily: 'var(--jx-font-sans)',
          fontSize: '13px',
          lineHeight: 1.4,
          color: selected ? 'var(--jx-text)' : 'var(--jx-text-2)',
        }}
      >
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' })}`
          : 'Дата не выбрана — нажмите быстрый вариант или день в календаре.'}
      </p>
    </div>
  );
}

